<?php $edit=(bool)$application;$action=$edit?'/admin/applications/'.$application['id'].'/edit':'/admin/applications/create';?>
<form class="panel form-panel" method="post" action="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to($action)) ?>"><input type="hidden" name="_csrf" value="<?= \CardPay\Core\View::e($csrf) ?>"><div class="panel-head"><div><h2><?= $edit?'مشخصات پروژه':'اتصال پروژه جدید' ?></h2><p>هر پروژه کلید و تنظیمات پرداخت مستقل دارد.</p></div></div><div class="fields two"><label>نام پروژه<input name="name" value="<?= \CardPay\Core\View::e($application['name']??'') ?>" required></label><label>Slug<input name="slug" value="<?= \CardPay\Core\View::e($application['slug']??'') ?>" pattern="[a-z0-9][a-z0-9_-]{1,79}" <?= $edit?'readonly':'' ?> required dir="ltr"></label><label class="full">توضیح<textarea name="description" rows="2"><?= \CardPay\Core\View::e($application['description']??'') ?></textarea></label><label>Webhook URL<input name="webhook_url" type="url" value="<?= \CardPay\Core\View::e($application['webhook_url']??'') ?>" dir="ltr"></label><label>Callback URL<input name="callback_url" type="url" value="<?= \CardPay\Core\View::e($application['callback_url']??'') ?>" dir="ltr"></label><label>دامنه‌های مجاز<textarea name="allowed_domains" rows="2" placeholder="example.com"><?= \CardPay\Core\View::e($application['allowed_domains']??'') ?></textarea></label><label>کارت پیش‌فرض<select name="default_bank_card_id"><option value="">انتخاب کنید</option><?php foreach($cards as$card):?><option value="<?= (int)$card['id'] ?>" <?= (int)($application['default_bank_card_id']??0)===(int)$card['id']?'selected':'' ?>><?= \CardPay\Core\View::e($card['title']) ?> — •••• <?= \CardPay\Core\View::e($card['card_number_last_four']) ?></option><?php endforeach;?></select></label><label>رقم توکن<select name="token_digits"><option value="3" <?= (int)($application['token_digits']??3)===3?'selected':'' ?>>۳ رقم</option><option value="2" <?= (int)($application['token_digits']??3)===2?'selected':'' ?>>۲ رقم</option></select></label><label>اعتبار پرداخت (دقیقه)<input name="payment_expiration_minutes" type="number" min="1" max="10080" value="<?= (int)($application['payment_expiration_minutes']??30) ?>"></label><?php if($edit):?><label class="switch"><input type="checkbox" name="is_active" value="1" <?= $application['is_active']?'checked':'' ?>><span>پروژه فعال باشد</span></label><?php endif;?></div><div class="form-actions"><a class="btn secondary" href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/applications')) ?>">انصراف</a><button class="btn primary" type="submit">ذخیره پروژه</button></div></form>
